package com.registration.dao;
import com.registration.model.Student;import com.registration.util.DBConnection;import java.sql.*;import java.util.*;
public class StudentDAO{private static final String INS="INSERT INTO students(full_name,email,phone,gender,course,date_of_birth,address) VALUES(?,?,?,?,?,?,?)";private static final String SEL="SELECT id,full_name,email,phone,gender,course,date_of_birth,address FROM students ORDER BY id DESC";public boolean insertStudent(Student s)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(INS)){p.setString(1,s.getFullName());p.setString(2,s.getEmail());p.setString(3,s.getPhone());p.setString(4,s.getGender());p.setString(5,s.getCourse());p.setDate(6,Date.valueOf(s.getDateOfBirth()));p.setString(7,s.getAddress());return p.executeUpdate()==1;}}public List<Student> getAllStudents()throws SQLException{List<Student>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(SEL);ResultSet r=p.executeQuery()){while(r.next()){Student s=new Student();s.setId(r.getInt(1));s.setFullName(r.getString(2));s.setEmail(r.getString(3));s.setPhone(r.getString(4));s.setGender(r.getString(5));s.setCourse(r.getString(6));s.setDateOfBirth(r.getDate(7).toLocalDate());s.setAddress(r.getString(8));a.add(s);}}return a;}}